INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('f45407e8-10bb-4056-ba72-db81b672e2f9', '21feff02-016d-46e2-bb9d-c27495133b1b', '71. óra: Egyenes arányosság', 'Egyenes arányosság tulajdonságai: hányados állandó, megkétszereződés esetén a másik is megkétszereződik.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "0cd94392-e363-424a-939e-2fceeb194146", "text": "Mit jelent az egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "432bfbe8-3bc2-458c-9700-8a3446fcc801", "text": "Ha az egyik mennyiség hányszorosára változik, a másik mennyiség is ugyanannyiszorosára változik", "isCorrect": true}, {"id": "b6220f20-43c0-4954-9bcb-3a662b4de171", "text": "Ha az egyik nő, a másik felére csökken", "isCorrect": false}, {"id": "79e4b6f0-dc14-42ea-93c1-d627e344e83c", "text": "Ha a két mennyiség összege 100", "isCorrect": false}, {"id": "776d4ac8-084c-4683-a7a2-4673ad3f2717", "text": "Ha a két mennyiség szorzata állandó", "isCorrect": false}], "timeLimit": 15}, {"id": "e196b612-33a0-41b2-943e-a3dd4c84930a", "text": "Egyenes arányosság esetén a két összetartozó érték hányadosa állandó.", "type": "true-false", "options": [{"id": "f3d52c1e-d8de-479d-9b70-3da61dc9c58e", "text": "Igaz", "isCorrect": true}, {"id": "e58a696d-00cb-4648-b160-73f514d6c313", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "55ef402e-624f-46f8-b15a-69d4610fd387", "text": "Ha 2 kg alma 800 Ft, mennyibe kerül 6 kg alma? (800 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2400"}, {"id": "9108a18e-ff16-4c71-b91e-0ec7e51ea49a", "text": "Ha 3 füzet 600 Ft, mennyibe kerül 1 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "2b3f78ad-d582-4af8-83e8-2e7a563f0114", "text": "Melyik pár között van egyenes arányosság?", "type": "multiple-choice", "options": [{"id": "8e439a85-a773-461f-87b5-e2f81929a451", "text": "Az azonos árú termék tömege és a fizetendő összeg", "isCorrect": true}, {"id": "0d17ea7b-dfb3-46c3-abde-0f334392ce09", "text": "Az ember életkora és a magassága felnőttként", "isCorrect": false}, {"id": "a2d29ffa-8212-4398-a54a-94317ec2480c", "text": "A téglalap két oldala rögzített területnél", "isCorrect": false}, {"id": "e62aa743-e1f6-427a-9555-d70820e57b30", "text": "A sebesség és az idő adott úton", "isCorrect": false}], "timeLimit": 15}, {"id": "197b6f8b-e35c-4473-b4d9-259a6a50d0e9", "text": "Ha a megvásárolt mennyiséget felére csökkentjük, a fizetendő ár is a felére csökken.", "type": "true-false", "options": [{"id": "27ac80f0-7ed0-480f-b1db-f9e2640b39f0", "text": "Igaz", "isCorrect": true}, {"id": "0ebc470e-73c1-489c-8585-18bcd80224e7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ce510bda-d8da-4f11-a80f-9bad7bfe0de1", "text": "Ha 5 l üdítő 2000 Ft, mennyi 10 l üdítő ára? (Ft-ban)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}]'::jsonb, true, NOW()),
('bd36ff13-e05c-4134-b9b2-5a3d10453f96', '21feff02-016d-46e2-bb9d-c27495133b1b', '72. óra: Egyenes arányosság grafikonja', 'Az egyenes arányosság ábrázolása a derékszögű koordináta-rendszerben.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "9833fe2c-fcf2-4696-9506-d1be9a92d4a3", "text": "Milyen alakzat az egyenes arányosság grafikonja a koordináta-rendszerben?", "type": "multiple-choice", "options": [{"id": "cc436018-1b3c-4ebb-8f0d-3d31aff3c392", "text": "Az origóból (0; 0) induló félegyenes (vagy egyenes)", "isCorrect": true}, {"id": "076fd48e-1025-4518-a157-9669e0182cab", "text": "Parabola", "isCorrect": false}, {"id": "c1e6dea6-84c3-44b2-a6d1-019d81b1af8f", "text": "Körvonal", "isCorrect": false}, {"id": "e64d08fe-9d08-4504-9273-d1575b5dcfb6", "text": "Vízszintes egyenes", "isCorrect": false}], "timeLimit": 15}, {"id": "89cbc65c-eea0-442f-bb8a-91af7c78e2c7", "text": "Áthalad-e az egyenes arányosság grafikonja az origón (0; 0)?", "type": "true-false", "options": [{"id": "0c429f4b-12da-4456-9eb1-31ebfca4e3eb", "text": "Igaz (0 mennyiség ára 0 Ft)", "isCorrect": true}, {"id": "5ba9b217-2c74-4e20-8fff-42dcf143b30b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b0c5dd79-7802-4a8c-a928-6c1a541c3f58", "text": "Ha a grafikon áthalad a (1; 300) ponton, mennyi az egységérték?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "8b0ad802-31d0-4b2a-a0b1-1daefcf09ce1", "text": "Ha a grafikon áthalad a (1; 300) ponton, hol metszi a 4-es értéket az y tengelyen? (4 * 300)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}, {"id": "cf3f871e-73e7-465b-8e57-3642fde9d2b4", "text": "A grafikonról leolvashatók az összetartozó értékpárok.", "type": "true-false", "options": [{"id": "ea29e56b-54cf-4cb2-a482-71f520716eb1", "text": "Igaz", "isCorrect": true}, {"id": "fc3e9d54-3eac-4f79-85c8-d47e05ec6683", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d6506a9-af29-420e-b0ff-e3e2c23a7ec9", "text": "Egyenes arányosságnál a meredekség megadja az egységárat.", "type": "true-false", "options": [{"id": "2ad43813-c37b-4349-9416-3cbec2c0b3fe", "text": "Igaz", "isCorrect": true}, {"id": "0327f8b6-aaee-49d7-8b44-e3669ebf5a3a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5fd4700f-314f-4240-8e88-f8a8704f123c", "text": "Ha 0 kg áru 0 Ft, a grafikon a (0;0) pontból indul.", "type": "true-false", "options": [{"id": "e1b970ad-5400-46fe-bb2d-d662f82df80a", "text": "Igaz", "isCorrect": true}, {"id": "c4d092dd-d6f5-4c4a-84d6-acb1401fe8c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('44c8a988-5f84-4ea8-b7cb-28ff9d199180', '21feff02-016d-46e2-bb9d-c27495133b1b', '73. óra: Gyakorlóóra', 'Gyakorlati feladatok egyenes arányosságra, táblázatkitöltés, grafikon leolvasás.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "d649b510-83c6-4ab5-a071-6b52dbf13b1a", "text": "Ha 4 méter szalag 1000 Ft, mennyibe kerül 7 méter szalag? (1000/4 = 250 Ft/m, 250*7)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1750"}, {"id": "f9f9f68f-9272-4bbf-a1cc-f88fd33ee18e", "text": "Egy autó 100 km-en 7 liter benzint fogyaszt. Hány litert fogyaszt 400 km-en?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "28"}, {"id": "6ef9c2ed-a286-4165-bb07-35d338310040", "text": "Ha 2 óra alatt 120 km-t tesz meg a vonat állandó sebességgel, hány km-t tesz meg 5 óra alatt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "dd51fa28-19ff-449a-83e6-6a3aecb1797e", "text": "Az egységár meghatározása megkönnyíti a tetszőleges mennyiség árának kiszámítását.", "type": "true-false", "options": [{"id": "1c5fccac-8b49-4825-ad72-42a9421498e9", "text": "Igaz", "isCorrect": true}, {"id": "d6d201b5-0918-4e64-aa9a-71e3679aa97a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2db2b1ba-d151-4d0a-b29b-1d8233a8bb10", "text": "Ha 10 füzet 2500 Ft, mennyibe kerül 4 füzet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "e3f069ae-a0fd-412c-8f13-3cfe2cac2dea", "text": "Egyenes arányosságnál ha a független változót megháromszorozzuk, a függő változó is megháromszorozódik.", "type": "true-false", "options": [{"id": "fb0bc5f7-b4ee-481d-b30e-2b86cc716af6", "text": "Igaz", "isCorrect": true}, {"id": "b9a5717b-24f3-428e-98e4-6728c2372b01", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b9772113-2321-4a7a-9236-23e4c209e6cc", "text": "Ha 1 kg sajt 4000 Ft, mennyibe kerül 0,25 kg sajt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()),
('8b3a0c2a-cb7e-4739-80ed-ab830ad91fa1', '21feff02-016d-46e2-bb9d-c27495133b1b', '74. óra: Matematikai játékok', 'Sorozatok szabályai, játékos arányossági feladatok, csoportszervezés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "1804d975-0cd2-4bc3-be29-97a4a4041872", "text": "Mi a hiányzó szám a sorozatban: 2, 5, 8, 11, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "c1764019-9abe-4238-9783-b74c6f01d325", "text": "Mi a szabálya a 2, 4, 8, 16, 32 sorozatnak?", "type": "multiple-choice", "options": [{"id": "aa55cef6-1925-4e79-8616-34d22d6d32af", "text": "Szorzás 2-vel (*2)", "isCorrect": true}, {"id": "7d6cf79b-108e-4849-9183-9a8d4d54a083", "text": "Hozzáadás 2-vel (+2)", "isCorrect": false}, {"id": "2eef33ed-7f31-41de-8ab2-b95d41f17a4f", "text": "Négyzetre emelés", "isCorrect": false}, {"id": "2b2bde21-6f7b-441f-99ca-10ea0e665f5d", "text": "Kivonás 2-vel", "isCorrect": false}], "timeLimit": 15}, {"id": "475e555f-82c8-4211-b4fa-c4724461d696", "text": "A sorozatszabály megállapításához több egymást követő elem vizsgálata szükséges.", "type": "true-false", "options": [{"id": "1d9f4ddd-8d1b-4513-9bb8-5e6ab4e9a8b4", "text": "Igaz", "isCorrect": true}, {"id": "56dd0419-aed4-4274-8bde-e36667ff3333", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "52c847a0-8188-41d3-9d8c-5cd766ed230b", "text": "Mi a következő szám a 100, 90, 80, 70 sorozatban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "c7b0655b-872a-4ae3-8c25-d7bfae690ed7", "text": "Mi a hiányzó szám a Fibonacci sorozatban: 1, 1, 2, 3, 5, 8, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "13"}, {"id": "26627c72-dd32-4a50-afaa-1a9810b2952e", "text": "A növekvő számsorozatban az elemek értéke folyamatosan nő.", "type": "true-false", "options": [{"id": "ed001167-00bd-46b0-91a9-532d7fb53023", "text": "Igaz", "isCorrect": true}, {"id": "e1e31b41-9405-42fb-8893-9e15ce92d71a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b8c5f288-830d-415f-a6ad-4b7c2e97e3ad", "text": "Mi a szabálya a 3, 9, 27, 81 sorozatnak?", "type": "multiple-choice", "options": [{"id": "3dbcd552-dd9a-4c99-9080-f698fadd5732", "text": "Szorzás 3-mal (*3)", "isCorrect": true}, {"id": "72fb6c5c-8fab-43e8-8a0a-0f807e4be347", "text": "Hozzáadás 6-tal", "isCorrect": false}, {"id": "2377cad9-2133-41d4-82b5-9d98a013e4d3", "text": "Hozzáadás 3-mal", "isCorrect": false}, {"id": "294f65fb-fdeb-49b9-9f31-2170befd49b3", "text": "Osztás 3-mal", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('7fd13567-b0de-4cb0-85d4-a62ef5fab1b0', '21feff02-016d-46e2-bb9d-c27495133b1b', '75. óra: Szabályok, megfeleltetések', 'Sorozatok megadása képlettel, alakzat-sorozatok, szabályfelismerés.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "23281994-f148-4136-bac7-4e795fdbb684", "text": "Ha a sorozat nth elemének szabálya: a_n = 3 * n, mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "35c5dc0f-976b-4574-866b-2fb155023543", "text": "Ha a sorozat szabálya: a_n = 2 * n + 1, mennyi a 5. elem? (2*5 + 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "1c023856-421f-45eb-b87d-fe59324041e7", "text": "A számsorozatok a mindennapi mérésekben és a természetben is megjelennek.", "type": "true-false", "options": [{"id": "f74848ee-779d-4fa0-b356-b1faa9de174b", "text": "Igaz", "isCorrect": true}, {"id": "d5479493-c253-4150-abdb-7ba37c3216ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "db756a56-8fd2-4da5-b226-359c6779a1c5", "text": "Ha a sorozat szabálya a_n = n * n (négyzetszámok), mennyi a 4. elem?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "0b1ff1e0-6fa9-41ca-8c11-7c613b5d370e", "text": "Melyik sorozat szabálya a ''Hozzáadás 5-tel''?", "type": "multiple-choice", "options": [{"id": "77f28484-0557-4bc5-9561-a89576b53ac3", "text": "5, 10, 15, 20, 25", "isCorrect": true}, {"id": "a446f016-d7ce-491b-b587-bb5d5eb9fec4", "text": "5, 25, 125", "isCorrect": false}, {"id": "49da359c-ce24-4edf-a727-94098f4ae5ec", "text": "5, 4, 3, 2", "isCorrect": false}, {"id": "186bd934-7494-4fcb-9d34-a174ce37b52b", "text": "1, 2, 4, 8", "isCorrect": false}], "timeLimit": 15}, {"id": "9465497a-3e17-454e-a2f0-e487b2fdb41a", "text": "Az alakzat-sorozatoknál az elemek száma (pl. gyufaszálak száma) számsorozatot alkot.", "type": "true-false", "options": [{"id": "ac1c5197-cd3e-4670-99d4-727d1413e928", "text": "Igaz", "isCorrect": true}, {"id": "29088434-35d2-44db-ba23-22a5f75102a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c29752d8-182d-4926-b722-ae5e56cd0d5f", "text": "Mennyi a 10. páros természetes szám (2, 4, 6, ...)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()),
('6fe3e844-c991-4d9f-ab46-a32fd711c322', '21feff02-016d-46e2-bb9d-c27495133b1b', '76. óra: Gyakorlóóra', 'Gyakorló feladatok sorozatok szabályaira és egyenes arányosságra.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "cc5a6ed6-9097-4f8c-b1ef-ce777c1652e1", "text": "Mi a hiányzó szám a sorozatban: 1, 4, 9, 16, __, 36? (négyzetszámok)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "92515780-ba07-41a0-9c53-967edb90db2e", "text": "Mi a hiányzó szám: 50, 43, 36, 29, __? (kivonás 7-tel)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "f17bbb13-6023-4ccc-9380-141b351f8cce", "text": "Ha 3 kg narancs 1500 Ft, mennyi 1 kg narancs ára?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "500"}, {"id": "e29f57a0-bb3a-4630-8a19-bc3678fc301c", "text": "Ha 1 kg narancs 500 Ft, mennyibe kerül 8 kg narancs?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4000"}, {"id": "fe88c992-7384-4b24-bfb6-c831d8527fb0", "text": "Egy sorozatnak több különböző folytatása is elképzelhető, ha nem rögzítjük pontosan a szabályt.", "type": "true-false", "options": [{"id": "66335b48-c5a6-4a94-abac-9a53317e79a8", "text": "Igaz", "isCorrect": true}, {"id": "1baa05fa-71d5-4c2e-b19b-49bf58e321a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "03548bf0-9413-45c3-9169-59dc47f7c6ba", "text": "Mi a szabálya a 1, 3, 7, 15, 31 sorozatnak?", "type": "multiple-choice", "options": [{"id": "e1af90ba-b00b-47b3-ab06-24c899b6c9a2", "text": "Szorzás 2-vel és hozzáadás 1-gyel (*2 + 1)", "isCorrect": true}, {"id": "14f32d0d-d19b-4b7e-9dc9-38b65d8641cd", "text": "Hozzáadás 2-vel", "isCorrect": false}, {"id": "0b456268-f9a1-4723-9832-9aa5de1510a0", "text": "Szorzás 3-mal", "isCorrect": false}, {"id": "c3b5438d-ef5c-48c7-9448-a76406d0814b", "text": "Négyzetre emelés", "isCorrect": false}], "timeLimit": 15}, {"id": "a66673f8-7ef3-4d5b-9f3a-24b8a6c431cb", "text": "A számsorozatok logikus gondolkodásra nevelnek.", "type": "true-false", "options": [{"id": "f0aeeaad-d381-4809-b992-fe9a21869f9b", "text": "Igaz", "isCorrect": true}, {"id": "899f2437-60bd-425d-b60b-07960f1c7d3c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('355fb4cd-282c-4617-87d6-7eba129cbf10', '21feff02-016d-46e2-bb9d-c27495133b1b', '77. óra: Törtrész', 'Törtrész kiszámítása és kapcsolata az egyenes arányossággal.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "4b539b4b-7325-42db-be97-0403a8bd60e4", "text": "Hogyan számítjuk ki egy mennyiség 3/5 részét?", "type": "multiple-choice", "options": [{"id": "348b82f6-933b-4762-9f75-66e1068cdb93", "text": "Elosztjuk 5-tel és megszorozzuk 3-mal (vagy megszorozzuk 3/5-tel)", "isCorrect": true}, {"id": "53195d07-53ec-40bb-a29b-7d7875bd66ab", "text": "Megszorozzuk 5-tel és elosztjuk 3-mal", "isCorrect": false}, {"id": "97017d55-c3dd-4525-b53e-b37e9006c544", "text": "Hozzáadunk 3/5-öt", "isCorrect": false}, {"id": "cfd1b6e7-b5e5-45f5-8fdf-94c44020ac58", "text": "Kivonunk 3/5-öt", "isCorrect": false}], "timeLimit": 15}, {"id": "98fec532-05c0-4ee4-aa30-565d3d1608bc", "text": "Mennyi 80-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "056e9c5d-42dd-4729-824a-02dc3562f68f", "text": "Mennyi 150-nek a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "1c8a6099-6b77-4762-b185-1ddcef8bf30e", "text": "A törtrész kiszámítása egyenesen arányos a megadott tört nagyságával.", "type": "true-false", "options": [{"id": "5d04521a-b3f0-4790-aff3-a3ea47ec11da", "text": "Igaz", "isCorrect": true}, {"id": "1fbd5e25-88cd-4d45-b9b2-33ec3a6d3699", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4e211bed-22ca-4d8b-aa60-fe4ee9a30c99", "text": "Mennyi 200-nak az 1/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "ba449b99-fafe-4373-9df4-03ad85fca3e0", "text": "Ha egy mennyiség 1/2 része 30, mennyi a teljes mennyiség? (30 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "863bd4e5-adf2-49aa-8fbd-b1839490719f", "text": "Mennyi 90-nek a 4/9 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()),
('b43b88da-1eb5-427b-b076-8e14073c9f36', '21feff02-016d-46e2-bb9d-c27495133b1b', '78. óra: Feladatmegoldás', 'Összetett feladatok megoldása törtrész kiszámításával.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "bddf638a-964c-43c9-99ba-de8c50288f36", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldalt olvastunk el?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "c3257860-32fa-4406-8626-9a8c94cd359f", "text": "Egy 600 oldalú könyvnek elolvastuk a 3/5 részét. Hány oldal van még hátra? (600 - 360)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "240"}, {"id": "60a21ef1-a265-415f-850a-86b45549ac72", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ot költött el? (4000 * 3/8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "50fbaf5d-b595-4ea4-8aaf-8402cb89ba56", "text": "Kati zsebpénze 4000 Ft. Elköltötte a 3/8 részét. Hány Ft-ja maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "3e355ed2-75ac-46fb-bc6a-8679ac38c282", "text": "Ha a törtrész kiszámítása után a maradékot keresük, a teljesből kivonjuk a törtrészt.", "type": "true-false", "options": [{"id": "00f1fc98-628d-4c87-b5c0-5691d5fbf066", "text": "Igaz", "isCorrect": true}, {"id": "c6d8db48-ba16-48a0-9ae0-f3ec8501570d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b20426a2-05e1-4479-b76c-431d98cf1d80", "text": "Mennyi 120-nak a 5/6 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "fd5eedd2-7a58-4ce3-8a93-38bcd9c53648", "text": "A törtrész kiszámítása fontos a pénzügyi és mindennapi döntésekben.", "type": "true-false", "options": [{"id": "07956f0c-71bd-489a-8cac-941f7e037a94", "text": "Igaz", "isCorrect": true}, {"id": "a0ccad32-0362-4745-b04a-3c48645be997", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('284f5f43-0dbc-4303-a802-4c73fc2c84cc', '21feff02-016d-46e2-bb9d-c27495133b1b', '79. óra: Számonkérés', 'Számonkérés az arány, egyenes arányosság és törtrész témakörökből (10 kérdés).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "b07b25ef-7c6b-490b-a7ca-1167e60301cc", "text": "1. Mennyi a 6 : 18 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "64d196fc-980c-424f-a810-eafc6e828438", "text": "1 : 3", "isCorrect": true}, {"id": "1122ed4a-6c33-4355-a697-117c136b04f2", "text": "1 : 2", "isCorrect": false}, {"id": "5cd70464-46d2-4d40-a781-460137c8e584", "text": "3 : 1", "isCorrect": false}, {"id": "6f9797fc-3e61-4b13-8623-bd7efad8c42a", "text": "2 : 3", "isCorrect": false}], "timeLimit": 15}, {"id": "31c032cf-28b0-4163-93f4-5a83c3ad3c66", "text": "2. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a kisebbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "62434039-8dbf-4b0c-813e-86ddf3ff4c24", "text": "3. Ossz el 400 Ft-ot 1 : 3 arányban! Hány Ft a nagyobbik rész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "b422ec9c-d973-4c36-a724-812bf75caed6", "text": "4. Ha 3 kg alma 900 Ft, mennyibe kerül 5 kg alma?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1500"}, {"id": "f9a1aab3-1cc7-4f09-8a57-16d09f3c5953", "text": "5. Mennyi 120-nak a 3/4 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "162c2614-53e4-4d09-8d9e-d2f21f42f98d", "text": "6. Az egyenes arányosság grafikonja az origóból induló félegyenes.", "type": "true-false", "options": [{"id": "541a07e8-c57b-4917-8ef7-fce5116904ce", "text": "Igaz", "isCorrect": true}, {"id": "79ebd2e6-a3cf-4827-905f-78107564891b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c24677d-797d-4db8-aa98-1497dbd4dfae", "text": "7. Mi a hiányzó szám a sorozatban: 4, 8, 12, 16, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "054a75ee-952c-4255-b088-0bf3e78e3f0c", "text": "8. Ha egy mennyiség 1/3-a 15, mennyi az egész mennyiség?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "be74ce17-1e35-4b5d-b645-a1b71fcd4a6d", "text": "9. Két mennyiség aránya hányados formájában is felírható.", "type": "true-false", "options": [{"id": "1689df6d-fdf6-4e66-a6b6-c5e4d8e2b09a", "text": "Igaz", "isCorrect": true}, {"id": "2b943301-6593-4d17-812b-5d0d133dcc73", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "84d47f4e-128e-4576-a2cc-da24751ac4b3", "text": "10. Mennyi 50-nek a 4/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}]'::jsonb, true, NOW()),
('9bb7fc68-f416-4a60-a9ba-d4d1cfe15ff8', '21feff02-016d-46e2-bb9d-c27495133b1b', '80. óra: Létraverseny I.', 'Versenyszerű feladatmegoldás páros munkában az arányosságok témájában.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "114c753b-3ed4-4aa4-8464-83bf3b05a7f2", "text": "Ha 2 m szalag 400 Ft, mennyibe kerül 10 m szalag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "d7947e50-6327-43fc-8130-9c4bbd66ac14", "text": "Mennyi az 5 : 15 arány legegyszerűbb alakja?", "type": "multiple-choice", "options": [{"id": "8f7003f9-5439-4b8d-a15d-3c85a459deae", "text": "1 : 3", "isCorrect": true}, {"id": "64414c90-2f07-4711-88b2-ae43ba6c51a4", "text": "1 : 5", "isCorrect": false}, {"id": "dd292541-471b-4ea6-a26b-4c8da1d17e16", "text": "3 : 1", "isCorrect": false}, {"id": "f029404b-c7e8-402e-90a0-3ca38fb39677", "text": "1 : 2", "isCorrect": false}], "timeLimit": 15}, {"id": "e53c715a-c33d-476d-8764-8c14f42a6ceb", "text": "Mennyi 200-nak a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "120"}, {"id": "690a5737-53a3-46ef-a8e2-f8e0101d6a89", "text": "Mi a sorozat 5. eleme: 3, 6, 12, 24, __?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "68aa91de-c227-4be7-b8df-ad79795e6044", "text": "Az arányos osztásnál a részek összege kiadja az eredeti egészet.", "type": "true-false", "options": [{"id": "6d411257-6749-4781-97c3-85cd6c885df5", "text": "Igaz", "isCorrect": true}, {"id": "c8226942-c14e-414c-9489-c9b7b0ecd5c5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "70931a8d-9620-4e7b-ad36-9af3723c597c", "text": "Hány dl szörp kell 2 liter (1:4 arányú) hígított italhoz? (20 dl / 5 = 4 dl)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "92705508-4dec-41c9-937d-101a5743304c", "text": "A játékos versenyzés növeli a feladatmegoldási motivációt.", "type": "true-false", "options": [{"id": "fab9648e-f0a9-4d6f-8409-0be8cb772469", "text": "Igaz", "isCorrect": true}, {"id": "c66146d4-e14c-443a-9443-abc86ae04a0a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;